    except keybundle.BundleError:
        # Wrong passphrase, tampering, bad base64/JSON, format or
        # any internal version/field problem share one detail-free
        # 400: the failure never doubles as an existence probe.
        self._bad_request("invalid key export")
        return
    key_id = decoded["key_id"]
    # Authorization uses the import action scoped by the in-bundle
    # key_id, in the same order as /v1/keys/import (after decrypt,
    # before the occupancy check). A denial is the only audit event
    # a preflight ever writes.
    if not policy_store.is_allowed(
        tenant_id, audit_mod.ACTION_IMPORT, operator, key_id
    ):
