            store.audit_attempt(
                tenant_id, None, audit_mod.ACTION_IMPORT,
                audit_mod.OUTCOME_REJECTED,
            )
        except LedgerError:
            self._preflight_unavailable()
            return
        self._send_json(
            403, {"error": "action not permitted by policy"}

